import { api, formatDate, message, statusLabel, type Project, type Task } from "@/lib/task-api";

type Configuration = {
  research_configured: boolean;
  coding_configured: boolean;
  coding_missing_settings: string[];
  missing_settings: string[];
  tracing_configured: boolean;
  qualification: string;
};

export function TaskWorkspace() {
  const [projects, setProjects] = useState<Project[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [config, setConfig] = useState<Configuration | null>(null);
  const [projectId, setProjectId] = useState("");
  const [kind, setKind] = useState<"research" | "coding">("research");
  const [repository, setRepository] = useState("");
  const [repositoryRef, setRepositoryRef] = useState("main");
  const [issueNumber, setIssueNumber] = useState("");
  const [testProfile, setTestProfile] = useState("python_pytest");
  const [alsoBuild, setAlsoBuild] = useState(false);
  const [goal, setGoal] = useState("");
  const [cost, setCost] = useState("0.50");
  const [seconds, setSeconds] = useState("300");
  const [hosts, setHosts] = useState("");
  const [projectName, setProjectName] = useState("");
  const [error, setError] = useState("");
  const [submitError, setSubmitError] = useState("");
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [creatingProject, setCreatingProject] = useState(false);
  const [refresh, setRefresh] = useState(0);
  const [offset, setOffset] = useState(0);
  const [createdTask, setCreatedTask] = useState<Task | null>(null);

  useEffect(() => {
    const controller = new AbortController();
    let inFlight = false;
    async function load() {
      if (inFlight) return;
      inFlight = true;
      try {
        const [nextProjects, nextTasks, nextConfig] = await Promise.all([
          api<Project[]>("/projects", { signal: controller.signal }),
          api<Task[]>(`/tasks?limit=20&offset=${offset}`, { signal: controller.signal }),
          api<Configuration>("/configuration", { signal: controller.signal }),
        ]);
        if (!controller.signal.aborted) {
          setProjects(nextProjects);
          setProjectId((current) => nextProjects.some((project) => project.id === current) ? current : nextProjects[0]?.id ?? "");
          setTasks(nextTasks);
          setConfig(nextConfig);
          setError("");
        }
      } catch (error) {
        if (!controller.signal.aborted) setError(message(error));
      } finally {
        if (!controller.signal.aborted) setLoading(false);
        inFlight = false;
      }
    }
    void load();
    const timer = window.setInterval(() => { void load(); }, 10000);
    return () => { controller.abort(); window.clearInterval(timer); };
  }, [refresh, offset]);

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSubmitError("");
    const numericCost = Number(cost);
    const numericSeconds = Number(seconds);
    const allowedHosts = (kind === "research" ? hosts : "").split(/[\s,]+/).map((host) => host.trim().toLowerCase()).filter(Boolean);
    if (!projectId || goal.trim().length < 20 || goal.trim().length > 8000 || !Number.isFinite(numericCost) || numericCost <= 0 || numericCost > 5 || !Number.isInteger(numericSeconds) || numericSeconds < 30 || numericSeconds > 1200 || allowedHosts.length > 20) {
      setSubmitError("Choose a project, write at least 20 characters, and keep the limits within the ranges shown.");
      return;
    }
    if (kind === "coding" && (!/^[A-Za-z0-9-]+\/[A-Za-z0-9_.-]+$/.test(repository.trim()) || !repositoryRef.trim() || (issueNumber && (!/^\d+$/.test(issueNumber) || Number(issueNumber) < 1 || Number(issueNumber) > 2147483647)))) {
      setSubmitError("Enter owner/name, a branch or commit, and an optional positive issue number.");
      return;
    }
    setSubmitting(true);
    try {
      const task = await api<Task>("/tasks", { method: "POST", body: JSON.stringify({
        project_id: projectId, kind, goal: goal.trim(), max_cost_usd: cost,
        ...(kind === "coding" ? { coding: { repository: { repo_id: repository.trim(), ref: repositoryRef.trim() }, issue_number: issueNumber ? Number(issueNumber) : null, test_profiles: [testProfile], command_profiles: alsoBuild ? ["node_build"] : [], max_repair_attempts: 2 } } : {}),
        max_wall_time_sec: numericSeconds, allowed_web_hosts: allowedHosts,
      }) });
      // Show a durable receipt before navigation; a failed navigation must never
      // encourage an accidental second paid task submission.
      setCreatedTask(task);
      setGoal("");
      setOffset(0);
      setRefresh((value) => value + 1);
    } catch (error) { setSubmitError(message(error)); }
    finally { setSubmitting(false); }
  }

  return (
    <div className="grid items-start gap-12 lg:grid-cols-[minmax(0,1.05fr)_minmax(0,1fr)] lg:gap-16">
      <section aria-labelledby="composer-title" className="min-w-0 space-y-7">
        <div className="space-y-3">
          <h1 id="composer-title" className="text-3xl font-semibold tracking-tight">What would you like your agents to do?</h1>
          <p className="max-w-prose text-sm leading-relaxed text-muted-foreground">Research a question or prepare a code change. Set a budget, follow the work, and review the evidence before using the result.</p>
        </div>
        {loading ? <div aria-label="Loading workspace" className="space-y-4"><div className="h-10 rounded-lg bg-muted" /><div className="h-44 rounded-lg bg-muted" /></div> : null}
        {error ? <div role="alert" className="space-y-3"><p className="text-sm text-destructive">{error}</p><Button variant="outline" onClick={() => setRefresh((value) => value + 1)}>Retry</Button></div> : null}
        {config && !(kind === "coding" ? config.coding_configured : config.research_configured) ? (
          <div className="rounded-xl border bg-muted/30 p-4 text-sm leading-relaxed">
            <p className="font-medium">{kind === "coding" ? "Coding setup is incomplete" : "Research setup is incomplete"}</p>
            <p className="mt-1 text-muted-foreground">Configure the following API settings, restart the API and worker, then refresh this page:</p>
            <ul className="mt-3 list-inside list-disc break-words text-xs leading-6">{(kind === "coding" ? config.coding_missing_settings : config.missing_settings).map((name) => <li key={name}><code>{name}</code></li>)}</ul>
          </div>
        ) : null}
        {config && !config.tracing_configured ? <p className="text-xs leading-relaxed text-muted-foreground">Neatlogs tracing is not configured. Tasks can run, but external trace delivery requires NEATLOGS_API_KEY.</p> : null}
        {!loading && !projects.length && !error ? (
          <form className="space-y-3 rounded-xl border p-4" onSubmit={async (event) => {
            event.preventDefault(); setCreatingProject(true); setSubmitError("");
            try {
              const project = await api<Project>("/projects", { method: "POST", body: JSON.stringify({ name: projectName.trim() }) });
              setProjects([project]); setProjectId(project.id); setProjectName("");
            } catch (error) { setSubmitError(message(error)); }
            finally { setCreatingProject(false); }
          }}>
            <p className="text-sm font-medium">Create a project to organize your tasks</p>
            <label htmlFor="project-name" className="sr-only">Project name</label>
            <input id="project-name" className={inputClass} placeholder="Project name" required maxLength={100} value={projectName} onChange={(event) => setProjectName(event.target.value)} disabled={creatingProject} />
            <Button type="submit" disabled={creatingProject}><Plus aria-hidden="true" />{creatingProject ? "Creating…" : "Create project"}</Button>
          </form>
        ) : null}
        <form onSubmit={submit} className="space-y-5" aria-busy={submitting}>
          <div className="space-y-2">
            <label htmlFor="task-kind" className="text-sm font-medium">Task type</label>
            <select id="task-kind" className={inputClass} value={kind} onChange={(event) => setKind(event.target.value as "research" | "coding")} disabled={submitting}>
              <option value="research">Research</option><option value="coding">Code change</option>
            </select>
          </div>
          <div className="space-y-2">
            <label htmlFor="project" className="text-sm font-medium">Project</label>
            <select id="project" required className={inputClass} value={projectId} onChange={(event) => setProjectId(event.target.value)} disabled={loading || submitting || !projects.length}>
              {!projects.length ? <option value="">No projects available</option> : null}
              {projects.map((project) => <option key={project.id} value={project.id}>{project.name}</option>)}
            </select>
          </div>
          {kind === "coding" ? <fieldset className="space-y-4 border-t pt-5" disabled={submitting}>
            <legend className="px-1 text-sm font-medium">Public GitHub repository</legend>
            <div className="space-y-2"><label htmlFor="repository" className="text-sm">Repository owner/name</label><input id="repository" className={inputClass} required maxLength={140} value={repository} onChange={(event) => setRepository(event.target.value)} placeholder="owner/repository" autoCapitalize="none" spellCheck={false} /></div>
            <div className="space-y-2"><label htmlFor="repository-ref" className="text-sm">Branch, tag, or full commit SHA</label><input id="repository-ref" className={inputClass} required maxLength={200} value={repositoryRef} onChange={(event) => setRepositoryRef(event.target.value)} autoCapitalize="none" spellCheck={false} /><p className="text-xs leading-relaxed text-muted-foreground">The server pins this ref to an immutable commit before queuing. Private repositories are unavailable.</p></div>
            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-2"><label htmlFor="issue-number" className="text-sm">Issue number (optional)</label><input id="issue-number" className={inputClass} type="number" min="1" max="2147483647" step="1" value={issueNumber} onChange={(event) => setIssueNumber(event.target.value)} /></div>
              <div className="space-y-2"><label htmlFor="test-profile" className="text-sm">Test profile</label><select id="test-profile" className={inputClass} value={testProfile} onChange={(event) => setTestProfile(event.target.value)}><option value="python_pytest">Python · pytest</option><option value="python_unittest">Python · unittest</option><option value="node_npm_test">Node · npm test</option></select></div>
            </div>
            <div className="space-y-2">
              <label htmlFor="also-build" className="flex items-center gap-3 text-sm"><input id="also-build" type="checkbox" className="size-4 accent-primary focus-visible:outline-2 focus-visible:outline-offset-2" checked={alsoBuild} onChange={(event) => setAlsoBuild(event.target.checked)} aria-describedby="also-build-help" />Also run npm build</label>
              <p id="also-build-help" className="text-xs leading-relaxed text-muted-foreground">Optional. Uses the same task budget. The E2B template must already have the repository&apos;s build dependencies installed.</p>
            </div>
            <p className="text-xs leading-relaxed text-muted-foreground">Code runs in an E2B managed sandbox. Review the patch and actual test logs; these tasks do not publish changes to GitHub.</p>
          </fieldset> : null}
          <div className="space-y-2">
            <label htmlFor="goal" className="text-sm font-medium">{kind === "coding" ? "Change request" : "Research question"}</label>
            <textarea id="goal" className={`${inputClass} min-h-44 resize-y leading-relaxed`} placeholder={kind === "coding" ? "Describe the change, expected behavior, and acceptance criteria." : "Describe the question, the evidence you need, and what a useful answer should include."} minLength={20} maxLength={8000} required value={goal} onChange={(event) => setGoal(event.target.value)} disabled={submitting || loading} aria-describedby="goal-help" />
            <p id="goal-help" className="text-xs text-muted-foreground">20–8,000 characters. Be specific about the desired outcome.</p>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2"><label htmlFor="cost" className="text-sm font-medium">Maximum cost (USD)</label><input id="cost" className={`${inputClass} tabular-nums`} type="number" min="0.0001" max="5" step="0.0001" required value={cost} onChange={(event) => setCost(event.target.value)} disabled={submitting} aria-describedby="cost-help" /><p id="cost-help" className="text-xs text-muted-foreground">Up to $5 per task</p></div>
            <div className="space-y-2"><label htmlFor="seconds" className="text-sm font-medium">Time limit (seconds)</label><input id="seconds" className={`${inputClass} tabular-nums`} type="number" min="30" max="1200" step="1" required value={seconds} onChange={(event) => setSeconds(event.target.value)} disabled={submitting} aria-describedby="time-help" /><p id="time-help" className="text-xs text-muted-foreground">30–1,200 seconds</p></div>
          </div>
          {kind === "research" ? <details className="text-sm">
            <summary className="cursor-pointer font-medium outline-none focus-visible:ring-2 focus-visible:ring-ring">Restrict source domains</summary>
            <div className="mt-3 space-y-2"><label htmlFor="hosts" className="text-sm">Allowed public domains</label><input id="hosts" className={inputClass} value={hosts} onChange={(event) => setHosts(event.target.value)} disabled={submitting} placeholder="docs.example.com, example.org" aria-describedby="hosts-help" /><p id="hosts-help" className="text-xs leading-relaxed text-muted-foreground">Optional. Agents can retrieve public sources discovered by this task&apos;s search. Add up to 20 exact domains to restrict retrieval further. Separate domains with commas; subdomains need their own entry.</p></div>
          </details> : null}
          {submitError ? <p role="alert" className="text-sm text-destructive">{submitError}</p> : null}
          {createdTask ? <div role="status" className="rounded-xl border bg-muted/30 p-4 text-sm"><p>{createdTask.kind === "coding" ? "Coding task" : "Research task"} created.</p><Link href={`/tasks/${createdTask.id}`} className="mt-2 inline-flex items-center gap-2 font-medium underline underline-offset-4">Open task<ArrowRight aria-hidden="true" className="size-4" /></Link></div> : null}
          <Button type="submit" size="lg" disabled={submitting || loading || !projectId || !(kind === "coding" ? config?.coding_configured : config?.research_configured)}>{submitting ? "Creating task…" : kind === "coding" ? "Start code change" : "Start research"}<ArrowRight aria-hidden="true" /></Button>
          <p className="max-w-prose text-xs leading-relaxed text-muted-foreground">Task creation queues work for the separate worker. Configuration presence does not confirm that a worker or provider is available.</p>
        </form>
      </section>

      <section aria-labelledby="recent-title" className="min-w-0 border-t pt-7 lg:border-t-0 lg:pt-0">
        <div className="mb-5 flex items-center justify-between gap-3"><h2 id="recent-title" className="text-lg font-semibold">Recent tasks</h2><Button variant="ghost" size="sm" onClick={() => setRefresh((value) => value + 1)} disabled={loading}><RefreshCw aria-hidden="true" />Refresh</Button></div>
        {loading ? <div aria-label="Loading tasks" className="space-y-3">{[0, 1, 2].map((item) => <div key={item} className="h-20 rounded-lg bg-muted" />)}</div> : !tasks.length ? <div className="border-y py-10"><p className="text-sm font-medium">{offset ? "No more tasks" : "Your work starts here"}</p><p className="mt-2 text-sm leading-relaxed text-muted-foreground">{offset ? "Return to the previous page to see earlier results." : "Create a task to see its plan, agent runs, and evidence in this workspace."}</p></div> : <ul className="divide-y border-y">{tasks.map((task) => <li key={task.id}><Link href={`/tasks/${task.id}`} className="block space-y-2 py-5 outline-none hover:bg-muted/30 focus-visible:ring-2 focus-visible:ring-ring"><div className="flex flex-wrap items-center justify-between gap-2"><Badge variant={task.status === "FAILED" ? "destructive" : "secondary"}>{statusLabel(task.status)}</Badge><time dateTime={task.created_at} className="text-xs text-muted-foreground">{formatDate(task.created_at)}</time></div><p className="line-clamp-2 text-sm font-medium leading-relaxed">{task.goal}</p><p className="text-xs text-muted-foreground">{projects.find((project) => project.id === task.project_id)?.name ?? "Project"} · ${task.max_cost_usd} limit</p></Link></li>)}</ul>}
        {offset || tasks.length === 20 ? <div className="mt-4 flex justify-between gap-3"><Button variant="outline" size="sm" disabled={!offset} onClick={() => { setLoading(true); setOffset((value) => Math.max(0, value - 20)); }}>Previous</Button><Button variant="outline" size="sm" disabled={tasks.length < 20 || offset >= 9980} onClick={() => { setLoading(true); setOffset((value) => value + 20); }}>Next</Button></div> : null}
      </section>
    </div>
  );
}
"use client";

import { useEffect, useState, type ReactNode } from "react";
import { Download, ExternalLink, RefreshCw } from "lucide-react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { api, eventTypes, formatDate, message, publicSourceUrl, statusLabel, terminalStatuses,
  type AgentRun, type Artifact, type CodingDetail, type Source, type Task, type TaskEvent, type TaskStep } from "@/lib/task-api";

type Detail = { task: Task; steps: TaskStep[]; runs: AgentRun[]; sources: Source[]; artifacts: Artifact[]; coding: CodingDetail | null };
type ClaimCheck = { claim: string; source_ids: string[]; status: string; reason: string };

function Panel({ title, children }: { title: string; children: ReactNode }) {
  return <section className="min-w-0 space-y-4 border-t pt-6"><h2 className="text-base font-semibold">{title}</h2>{children}</section>;
}

function checksFrom(value: unknown): ClaimCheck[] {
  if (!Array.isArray(value)) return [];
  return value.filter((item): item is ClaimCheck => item !== null && typeof item === "object" &&
    typeof item.claim === "string" && typeof item.status === "string" && typeof item.reason === "string" &&
    Array.isArray(item.source_ids) && item.source_ids.every((id: unknown) => typeof id === "string"));
}
function stringsFrom(value: unknown): string[] {
  return Array.isArray(value) ? value.filter((item): item is string => typeof item === "string") : [];
}
function recordFrom(value: unknown): Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : {};
}

export function TaskDetail({ taskId }: { taskId: string }) {
  const [detail, setDetail] = useState<Detail | null>(null);
  const [events, setEvents] = useState<TaskEvent[]>([]);
  const [connection, setConnection] = useState("Connecting");
  const [error, setError] = useState("");
  const [actionError, setActionError] = useState("");
  const [cancelling, setCancelling] = useState(false);
  const [refresh, setRefresh] = useState(0);

  useEffect(() => {
    const controller = new AbortController();
    let cursor = 0;
    let inFlight = false;
    let terminal = false;
    let scheduled: ReturnType<typeof setTimeout> | undefined;
    let stream: EventSource | undefined;

    function append(page: TaskEvent[]) {
      if (controller.signal.aborted || !page.length) return;
      const scoped = page.filter((event) => event.task_id === taskId && Number.isSafeInteger(event.sequence));
      if (!scoped.length) return;
      cursor = Math.max(cursor, ...scoped.map((event) => event.sequence));
      setEvents((current) => [...new Map([...current, ...scoped].map((event) => [event.sequence, event])).values()]
        .sort((a, b) => a.sequence - b.sequence).slice(-200));
    }

    async function catchUp() {
      // Paginate in bounded batches; a busy stream cannot monopolize the browser.
      for (let pageNumber = 0; pageNumber < 10 && !controller.signal.aborted; pageNumber++) {
        const page = await api<TaskEvent[]>(`/tasks/${taskId}/events/history?after=${cursor}&limit=100`, { signal: controller.signal });
        append(page);
        if (page.length < 100) break;
      }
    }

    async function load() {
      if (inFlight || controller.signal.aborted) return;
      inFlight = true;
      try {
        const base = `/tasks/${taskId}`;
        const [task, steps, runs, sources, artifacts] = await Promise.all([
          api<Task>(base, { signal: controller.signal }),
          api<TaskStep[]>(`${base}/steps`, { signal: controller.signal }),
          api<AgentRun[]>(`${base}/runs`, { signal: controller.signal }),
          api<Source[]>(`${base}/sources`, { signal: controller.signal }),
          api<Artifact[]>(`${base}/artifacts`, { signal: controller.signal }),
        ]);
        const coding = task.kind === "coding" ? await api<CodingDetail>(`${base}/coding`, { signal: controller.signal }) : null;
        await catchUp();
        if (!controller.signal.aborted) {
          setDetail({ task, steps, runs, sources, artifacts, coding });
          setError("");
          terminal = terminalStatuses.has(task.status) && cursor >= task.event_sequence;
          if (!stream) setConnection("Polling for updates");
          if (terminal) {
            stream?.close();
            setConnection("Up to date");
          }
        }
      } catch (error) {
        if (!controller.signal.aborted) setError(message(error));
      } finally { inFlight = false; }
    }

    if (typeof EventSource !== "undefined") {
      stream = new EventSource(`/api/v1/tasks/${taskId}/events?after=0`);
      stream.onopen = () => { if (!controller.signal.aborted) setConnection("Live updates"); };
      stream.onerror = () => { if (!controller.signal.aborted && !terminal) setConnection("Reconnecting · polling for updates"); };
      const receive = (raw: Event) => {
        try {
          const event = JSON.parse((raw as MessageEvent<string>).data) as TaskEvent;
          append([event]);
          if (!scheduled) scheduled = setTimeout(() => { scheduled = undefined; void load(); }, 300);
        } catch { setConnection("Reconnecting · polling for updates"); }
      };
      for (const type of eventTypes) stream.addEventListener(type, receive);
      stream.addEventListener("session.closed", () => {
        stream?.close();
        window.dispatchEvent(new Event("agentforge-session-expired"));
      });
    }
    void load();
    const polling = window.setInterval(() => { if (!terminal) void load(); }, 5000);
    return () => {
      controller.abort(); stream?.close(); window.clearInterval(polling);
      if (scheduled) clearTimeout(scheduled);
    };
  }, [taskId, refresh]);

  if (!detail) {
    return <div className="space-y-6">{error ? <div role="alert" className="space-y-4"><h1 className="text-2xl font-semibold">Task unavailable</h1><p className="text-sm text-destructive">{error}</p><Button variant="outline" onClick={() => setRefresh((value) => value + 1)}>Retry</Button></div> : <div aria-label="Loading task" className="space-y-6"><div className="h-9 w-2/3 rounded-lg bg-muted" /><div className="h-24 rounded-lg bg-muted" /><div className="h-64 rounded-lg bg-muted" /></div>}</div>;
  }
  const { task, steps, runs, sources, artifacts, coding } = detail;
  const finished = terminalStatuses.has(task.status);
  const verification = recordFrom(task.final_result?.verification);
  const checks = checksFrom(verification.checks);
  const limitations = stringsFrom(verification.limitations);

  return (
    <div className="space-y-9">
      <header className="space-y-5">
        <div className="flex flex-wrap items-center justify-between gap-4">
          <div className="flex flex-wrap items-center gap-3"><Badge variant={task.status === "FAILED" ? "destructive" : "secondary"}>{statusLabel(task.status)}</Badge><span className="text-xs text-muted-foreground" role="status">{connection}</span></div>
          <div className="flex flex-wrap gap-2"><Button variant="outline" size="sm" onClick={() => setRefresh((value) => value + 1)}><RefreshCw aria-hidden="true" />Refresh</Button>{!finished ? <Button variant="destructive" size="sm" disabled={cancelling || !!task.cancel_requested_at} onClick={async () => {
            setCancelling(true); setActionError("");
            try {
              const updated = await api<Task>(`/tasks/${taskId}/cancel`, { method: "POST" });
              setDetail((current) => current ? { ...current, task: updated } : current);
              setRefresh((value) => value + 1);
            } catch (error) { setActionError(message(error)); }
            finally { setCancelling(false); }
          }}>{task.cancel_requested_at ? "Cancellation requested" : cancelling ? "Requesting…" : "Cancel task"}</Button> : null}</div>
        </div>
        <h1 className="max-w-4xl whitespace-pre-wrap break-words text-2xl font-semibold leading-snug tracking-tight">{task.goal}</h1>
        <p className="text-xs leading-relaxed text-muted-foreground">Created {formatDate(task.created_at)} · ${task.max_cost_usd} cost limit · {task.max_wall_time_sec}s time limit</p>
        {task.status === "CREATED" ? <p className="max-w-prose text-sm leading-relaxed text-muted-foreground">Queued for the worker. If this does not change, check the worker process and its configuration. This page does not confirm worker liveness.</p> : null}
        {task.cancel_requested_at && !finished ? <p className="text-sm text-muted-foreground">Cancellation is cooperative. An in-flight operation may finish before the worker stops.</p> : null}
        {error || actionError ? <p role="alert" className="text-sm text-destructive">{actionError || error}{error ? " Displaying the last received task state." : ""}</p> : null}
      </header>

      <div className="grid items-start gap-10 xl:grid-cols-[minmax(0,1.6fr)_minmax(18rem,1fr)]">
        <div className="min-w-0 space-y-8">
          <Panel title={task.kind === "coding" ? "Code change outcome" : "Research outcome"}>
            {task.final_summary ? <p className="max-w-prose whitespace-pre-wrap break-words text-sm leading-7">{task.final_summary}</p> : <p className="text-sm leading-relaxed text-muted-foreground">{finished ? task.kind === "coding" ? "This task ended without a final code change summary. Review the execution evidence and timeline." : "This task ended without a final research summary. Review the timeline and any sources collected below." : task.kind === "coding" ? "The final summary will appear after code review and sandbox verification." : "The final summary will appear here after the worker verifies the research."}</p>}
            {task.error_code ? <p className="break-words text-sm text-destructive">Worker reported: <code>{task.error_code}</code></p> : null}
            {artifacts.length ? <div className="flex flex-col items-start gap-3">{artifacts.map((artifact) => <a key={artifact.id} href={`/api/v1/tasks/${taskId}/artifacts/${artifact.id}`} className="inline-flex items-center gap-2 text-sm font-medium underline underline-offset-4 focus-visible:outline-2"><Download aria-hidden="true" className="size-4" />Download {artifact.filename}<span className="font-normal text-muted-foreground">({Math.ceil(artifact.byte_size / 1024)} KB)</span></a>)}</div> : null}
            {checks.length ? <div className="space-y-4"><h3 className="text-sm font-medium">Claim checks</h3>{checks.map((check, index) => <div key={`${index}-${check.claim}`} className="space-y-2 rounded-xl border p-4"><Badge variant={check.status === "QUOTE_SUPPORTED" ? "secondary" : "outline"}>{statusLabel(check.status)}</Badge><p className="break-words text-sm leading-relaxed">{check.claim}</p><p className="text-xs leading-relaxed text-muted-foreground">{check.reason}</p>{check.source_ids.length ? <div className="flex flex-wrap gap-x-4 gap-y-2">{check.source_ids.map((sourceId, sourceIndex) => <a key={`${sourceId}-${sourceIndex}`} href={`#source-${sourceId}`} className="text-xs underline underline-offset-4 focus-visible:outline-2">Source {sources.findIndex((source) => source.id === sourceId) >= 0 ? sources.findIndex((source) => source.id === sourceId) + 1 : sourceId.slice(0, 8)}</a>)}</div> : null}</div>)}</div> : null}
            {limitations.length ? <div><h3 className="text-sm font-medium">Limitations</h3><ul className="mt-2 list-disc space-y-2 pl-5 text-sm leading-relaxed text-muted-foreground">{limitations.map((limitation, index) => <li key={`${index}-${limitation}`}>{limitation}</li>)}</ul></div> : null}
          </Panel>

          {task.kind === "coding" ? <CodingEvidence detail={coding} spec={task.coding} finished={finished} /> : <Panel title="Sources">
            {!sources.length ? <p className="text-sm leading-relaxed text-muted-foreground">{finished ? "No research sources were persisted for this task." : "Source records appear here as agents search and retrieve evidence."}</p> : <ol className="divide-y">{sources.map((source, index) => {
              const href = publicSourceUrl(source.url);
              return <li key={source.id} id={`source-${source.id}`} className="scroll-mt-8 space-y-3 py-5 first:pt-0"><div className="flex flex-wrap items-center gap-2"><span className="text-xs text-muted-foreground">Source {index + 1}</span><Badge variant={source.fetch_status === "FAILED" ? "destructive" : "outline"}>{statusLabel(source.fetch_status)}</Badge></div>{href ? <a href={href} target="_blank" rel="noopener noreferrer" className="inline-flex max-w-full items-start gap-2 text-sm font-medium underline underline-offset-4 focus-visible:outline-2"><span className="break-words">{source.title || source.url}</span><ExternalLink aria-hidden="true" className="mt-0.5 size-3 shrink-0" /></a> : <p className="break-words text-sm font-medium">{source.title || "Source"}</p>}<p className="break-all text-xs text-muted-foreground">{source.url}</p>{source.excerpt ? <p className="whitespace-pre-wrap break-words text-sm leading-relaxed text-muted-foreground">{source.excerpt}</p> : null}<p className="text-xs text-muted-foreground">Retrieved {formatDate(source.retrieved_at)}{source.fetch_status === "SEARCH_ONLY" ? " · Search preview; page not fetched" : ""}</p>{source.error_code ? <p className="text-xs text-destructive">{source.error_code}</p> : null}</li>;
            })}</ol>}
          </Panel>}
        </div>

        <aside className="min-w-0 space-y-8" aria-label="Execution details">
          <Panel title="Plan">
            {!steps.length ? <p className="text-sm leading-relaxed text-muted-foreground">{finished ? "No plan was persisted." : "Waiting for the worker to create a plan."}</p> : <ol className="space-y-5">{steps.map((step) => <li key={step.id} className="space-y-2"><div className="flex flex-wrap items-center gap-2"><Badge variant="outline">{statusLabel(step.status)}</Badge><span className="text-xs text-muted-foreground">{step.agent_type} v{step.definition_version}</span></div><p className="break-words text-sm font-medium leading-relaxed">{step.objective}</p>{step.acceptance_criteria.length ? <ul className="list-disc space-y-1 pl-4 text-xs leading-relaxed text-muted-foreground">{step.acceptance_criteria.map((criterion, index) => <li key={`${step.id}-${index}`}>{criterion}</li>)}</ul> : null}{step.depends_on.length ? <p className="text-xs text-muted-foreground">After: {step.depends_on.join(", ")}</p> : null}</li>)}</ol>}
          </Panel>
          <Panel title="Agent runs">
            <p className="text-xs leading-relaxed text-muted-foreground">Accounted costs may include conservative caps for usage whose actual charge is unknown.</p>
            {!runs.length ? <p className="text-sm text-muted-foreground">No agents have started yet.</p> : <ul className="space-y-4">{runs.map((run) => {
              const step = steps.find((step) => step.agent_run_id === run.id);
              return <li key={run.id} className="space-y-2 text-sm"><div className="flex flex-wrap items-center justify-between gap-2"><p className="font-medium">{step ? `${step.agent_type} v${step.definition_version}` : "Agent run"}</p><Badge variant="outline">{statusLabel(run.status)}</Badge></div><p className="text-xs tabular-nums text-muted-foreground">Reserved ${run.reserved_cost_usd ?? "unknown"} · Accounted {run.measured_cost_usd == null ? "not available" : `$${run.measured_cost_usd}`}</p>{run.started_at ? <p className="text-xs text-muted-foreground">Started {formatDate(run.started_at)}</p> : null}{run.error_code ? <p className="break-words text-xs text-destructive">{run.error_code}</p> : null}</li>;
            })}</ul>}
          </Panel>
          <Panel title="Timeline">
            <p className="text-xs text-muted-foreground">Server events only. Showing up to the latest 200 received events.</p>
            {!events.length ? <p className="text-sm text-muted-foreground">Waiting for persisted events.</p> : <ol className="space-y-4">{events.map((event) => <li key={event.sequence} className="space-y-1"><div className="flex items-baseline justify-between gap-2"><p className="break-words text-sm font-medium">{event.event_type.split(".").map(statusLabel).join(" · ")}</p><span className="text-xs tabular-nums text-muted-foreground">#{event.sequence}</span></div><time className="block text-xs text-muted-foreground" dateTime={event.created_at}>{formatDate(event.created_at)}</time>{typeof event.payload.tool === "string" ? <p className="text-xs text-muted-foreground">{event.payload.tool}</p> : null}{typeof event.payload.model === "string" ? <p className="text-xs text-muted-foreground">{event.payload.model}</p> : null}{typeof event.payload.status === "string" ? <p className="text-xs">{statusLabel(event.payload.status)}</p> : null}{typeof event.payload.error_code === "string" ? <p className="break-words text-xs text-destructive">{event.payload.error_code}</p> : null}</li>)}</ol>}
          </Panel>
        </aside>
      </div>
    </div>
  );
}


function CodingEvidence({ detail, spec, finished }: { detail: CodingDetail | null; spec: Task["coding"]; finished: boolean }) {
  const repository = detail?.session?.repo_id ?? spec?.repository.repo_id;
  const commit = detail?.session?.commit_sha ?? spec?.repository.ref;
  return <Panel title="Code and execution evidence">
    {repository ? <div className="space-y-2 text-xs text-muted-foreground"><p className="break-all">Repository: {repository}</p><p className="break-all">Pinned commit: <code>{commit}</code></p>{detail?.session ? <p className="break-all">Workspace revision: <code>{detail.session.revision}</code></p> : <p>{finished ? "No workspace was persisted." : "Waiting for the worker to prepare the workspace."}</p>}</div> : null}
    <p className="text-xs leading-relaxed text-muted-foreground">Test logs show the observed sandbox result. Code review is model evidence; it does not replace running tests or reviewing the downloaded patch.</p>
    {!detail?.evidence.length ? <p className="text-sm text-muted-foreground">{finished ? "No coding evidence was persisted for this task." : "Diffs, test logs, and review evidence appear as the worker persists them."}</p> : <ol className="space-y-6">{detail.evidence.map((evidence) => <li key={evidence.id} className="min-w-0 space-y-3 border-t pt-4">
      <div className="flex flex-wrap items-center gap-2"><h3 className="text-sm font-medium">{statusLabel(evidence.kind)}</h3>{typeof evidence.status === "string" ? <Badge variant="outline">{statusLabel(evidence.status)}</Badge> : null}{typeof evidence.exit_code === "number" ? <Badge variant={evidence.exit_code === 0 ? "secondary" : "destructive"}>Exit {evidence.exit_code}</Badge> : null}</div>
      <p className="break-all text-xs text-muted-foreground">Revision <code>{evidence.revision}</code></p>
      {typeof evidence.profile_id === "string" ? <p className="text-xs">Profile: <code>{evidence.profile_id}</code></p> : null}
      {typeof evidence.summary === "string" ? <p className="whitespace-pre-wrap break-words text-sm leading-relaxed">{evidence.summary}</p> : null}
